/**
 * The bars 1–14 additions to the approved Swiss and Riso shots that can each be switched off on its own (the story bible's 先保留、再加;
 * build sheet notes/b114/sheet.md §0). Off, the shot draws what v04 drew there, at v04's instants (moved with the map): the identity
 * gates of the sheet's §9 render each one off as well as on. The SCAN bar itself is the map (src/score/film.ts); `pov` only chooses how
 * it looks (the design's fallback rungs; the glass sculpture is the same in every rung).
 */
export type BuildThreads = {
  /** S05 (swiss 1): the lens, the Müller-Brockmann arcs and Saul Bass's cut-paper pieces; off = v04's S05 (the disc lands, the row rule, the slide, the blink on 1.4). */
  readonly lens: boolean;
  /** S06 (swiss 2): the giant face's hop on 2.1& and the red L-ticks re-acquiring his oval on each split. */
  readonly reacquire: boolean;
  /** S07b (swiss 4): 'full' the X-ray POV · 'lite' the colour backplate with only the red scanlines, stamps, reticle, readout and iris ring · false no POV (the hops as a HUD only). */
  readonly pov: 'full' | 'lite' | false;
  /** S08 (swiss 5): the Warhol wave, the guest's red card, the quarantine and the revival; off = v04's ripple and blink wave over the recast poster. */
  readonly infection: boolean;
  /** S08's headline and footer type cards (off: those 26 cards are blank cream cards, infected like the rest). */
  readonly typeCards: boolean;
  /** T2's backs (swiss 5.4): S09's plates converge into register on the fill's sixteenths, ×4 → ×1 (off: v04's backs; the flip itself is the same either way). */
  readonly register: boolean;
  /** A7 and A8: the signature as Swiss small print (525–539) and as the Riso press slug (riso 1). */
  readonly slugs: boolean;
  /** S12 (riso 4): the proof → print steps on the snare 16ths (off: v04's cut to the big face). */
  readonly printSteps: boolean;
  /** S12: the sky roller, the sea's steps and the halftone rings off the sun (off: v04's sky and its rays). */
  readonly sunRings: boolean;
  /**
   * N3: the Swiss corner is clear — no bar counter `NN/61` and no beat squares
   * on an ink tab over swiss 1–5 (off: v04's corner counter, which read `NN/36` in v04).
   */
  readonly cleanCorner: boolean;
  /**
   * N2: S07's giant cropped type behind the glass ω
   * is his own bytes, GLASS_TYPE (off: v04's "150" and "bpm").
   */
  readonly glassBytes: boolean;
};
export const BUILD_THREADS: BuildThreads = {
  // cleanCorner: false — the corner counter stays (the gag: the film counts itself; drop 2 18.2 echoes it).
  lens: true, reacquire: true, pov: 'full', infection: true, typeCards: true, register: true, slugs: true, printSteps: true, sunRings: true, cleanCorner: false, glassBytes: true,
};

