// ——— S08: the poster (swiss 5) ——————————————————————————————————————————————————————————————————————————————————————————————————

/** The poster grid: 16 × 9 cards of 120 px (T2's cards), card (col, row) centred at cardAt (src/shots/swiss.ts): (8, 4) is world (60, 0). */
export const S08_GRID = { cols: 16, rows: 9, cell: 120 } as const;
/**
 * His card (amber #FFB23E, the only amber in Swiss), the guest's (DEFENDER red, the only red card) and the corner: the two cells v04's
 * counter tab covered; with BUILD_THREADS.cleanCorner (N3) two blank cream cards the wave infects like the rest.
 */
export const S08_HERO: readonly [number, number] = [8, 4];
export const S08_GUEST: readonly [number, number] = [12, 2];
export const S08_COUNTER: readonly (readonly [number, number])[] = [[14, 0], [15, 0]];
/** The three copies the antivirus quarantines (threads A6 ×3): boxed by red cut-paper strips on 888, grey 888–892, revived as 2×2s on 900. */
export const S08_QUARANTINE: readonly (readonly [number, number])[] = [[7, 3], [10, 5], [6, 6]];

/** A silkscreen tint (Riso inks only: never red, never amber). */
export type Tint = 'pink' | 'blue' | 'yellow';
/** The Warhol tints, linear-ready hex (Riso pink, blue, yellow) and the quarantine grey. */
export const TINTS: Readonly<Record<Tint | 'grey', string>> = { pink: '#FF48B0', blue: '#0078BF', yellow: '#FFE800', grey: '#9A9A96' };

export type S08Card = {
  col: number;
  row: number;
  /** hero: his amber card · guest: the red card · counter: the corner (v04's counter tab; N3: a blank card) · headline / footer: a type card · face: a host. */
  kind: 'hero' | 'guest' | 'counter' | 'headline' | 'footer' | 'face';
  /** The face or the type card's character ('' for the counter). */
  text: string;
  /** Manhattan distance from his card: the infection wave reaches it on step ⌈d/2⌉ (src/score/build.ts infectFrame). */
  d: number;
  /** The copy's silkscreen tint once infected (every card but his and the guest's; the corner's are cornerTints'). */
  tint?: Tint;
  /** One of the three quarantined copies. */
  quarantine?: true;
};

const at = (c: readonly [number, number], col: number, row: number) => c[0] === col && c[1] === row;
const near = (c: readonly [number, number], col: number, row: number) => Math.max(Math.abs(c[0] - col), Math.abs(c[1] - row)) === 1;
/** A ￣-eyed face (the guest's eyes): never in the 8 cards round the guest. */
const guestEyed = (face: string) => /[￣‾¯]/u.test(face);

/**
 * The tints: hashed per card, so that no two 4-neighbours share a tint and no yellow card touches his amber one (the 8 cards round
 * (8, 4)); his card, the guest's and the counter's take none. Row by row, each card takes the first of its hashed order that its left
 * and upper neighbours and the amber rule allow, backtracking if none does.
 */
function tints(kinds: readonly (readonly string[])[]): (Tint | undefined)[][] {
  const { cols, rows } = S08_GRID;
  const out: (Tint | undefined)[][] = Array.from({ length: rows }, () => Array.from({ length: cols }, () => undefined));
  const cells: [number, number][] = [];
  for (let row = 0; row < rows; row++) for (let col = 0; col < cols; col++) if (!['hero', 'guest', 'counter'].includes(kinds[row][col])) cells.push([col, row]);
  const order = (col: number, row: number): Tint[] => {
    const all: Tint[] = ['pink', 'blue', 'yellow'];
    return all.map((t, i) => [t, hash(col, row, 91 + i)] as const).sort((a, b) => a[1] - b[1]).map(([t]) => t);
  };
  const ok = (col: number, row: number, t: Tint) =>
    !(t === 'yellow' && near(S08_HERO, col, row)) && (col === 0 || out[row][col - 1] !== t) && (row === 0 || out[row - 1][col] !== t);
  const place = (i: number): boolean => {
    if (i === cells.length) return true;
    const [col, row] = cells[i];
    for (const t of order(col, row)) {
      if (!ok(col, row, t)) continue;
      out[row][col] = t;
      if (place(i + 1)) return true;
    }
    out[row][col] = undefined;
    return false;
  };
  if (!place(0)) throw new Error('S08: no tinting satisfies the rules');
  return out;
}

/**
 * N3: the corner's two cards (S08_COUNTER) take tints after every other card is tinted — the first of each one's hashed order that its
 * left and lower neighbours allow — so no tint the poster was approved with changes.
 */
function cornerTints(out: (Tint | undefined)[][]): (Tint | undefined)[][] {
  for (const [col, row] of S08_COUNTER) {
    const all: Tint[] = ['pink', 'blue', 'yellow'];
    const order = all.map((t, i) => [t, hash(col, row, 91 + i)] as const).sort((a, b) => a[1] - b[1]).map(([t]) => t);
    const taken = [[col - 1, row], [col + 1, row], [col, row - 1], [col, row + 1]].map(([c, r]) => out[r]?.[c]);
    const t = order.find((x) => !taken.includes(x) && !(x === 'yellow' && near(S08_HERO, col, row)));
    if (!t) throw new Error(`S08: no tint for the corner card (${col}, ${row})`);
    out[row][col] = t;
  }
  return out;
}

/**
 * Every card of the S08 poster, row by row from the top-left (144): the headline across row 0 (cards 0–10), the footer across row 8
 * (cards 0–14), his card, the guest's, the counter's tab, and S08_FACES in card order on the other 114 — but never a ￣-eyed face in
 * the 8 cards round the guest (such a face swaps with the next eligible one).
 */
export const S08_CARDS: readonly S08Card[] = (() => {
  const { cols, rows } = S08_GRID;
  const kinds: S08Card['kind'][][] = Array.from({ length: rows }, (_, row) =>
    Array.from({ length: cols }, (_, col) => {
      if (at(S08_HERO, col, row)) return 'hero';
      if (at(S08_GUEST, col, row)) return 'guest';
      if (S08_COUNTER.some((c) => at(c, col, row))) return 'counter';
      if (row === 0 && col < [...S08_HEADLINE].length) return 'headline';
      if (row === rows - 1 && col < [...S08_FOOTER].length) return 'footer';
      return 'face';
    }),
  );
  const queue = [...S08_FACES];
  const tint = cornerTints(tints(kinds));
  const out: S08Card[] = [];
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const kind = kinds[row][col];
      let text = '';
      if (kind === 'hero') text = HERO;
      else if (kind === 'guest') text = GUEST;
      else if (kind === 'headline') text = [...S08_HEADLINE][col];
      else if (kind === 'footer') text = [...S08_FOOTER][col];
      else if (kind === 'face') {
        const k = near(S08_GUEST, col, row) ? queue.findIndex((f) => !guestEyed(f)) : 0;
        text = queue.splice(Math.max(0, k), 1)[0];
      }
      const d = Math.abs(col - S08_HERO[0]) + Math.abs(row - S08_HERO[1]);
      out.push({ col, row, kind, text, d, ...(tint[row][col] ? { tint: tint[row][col] } : {}), ...(S08_QUARANTINE.some((c) => at(c, col, row)) ? { quarantine: true as const } : {}) });
    }
  }
  if (queue.length) throw new Error(`S08: ${queue.length} faces left over`);
  return out;
})();

/** A quarantined copy revived (900) as a Four-Marilyns 2×2: four (•ω•) at em 20, at (±30, ±30) from the card centre, never red or amber. */
export type Marilyn = { dx: number; dy: number; tint: Tint | 'paper'; ink: 'ink' | 'paper'; off: readonly [number, number] };
const MARILYN: readonly Marilyn[] = [
  { dx: -30, dy: 30, tint: 'paper', ink: 'ink', off: [0, 0] }, // TL: ink on paper
  { dx: 30, dy: 30, tint: 'pink', ink: 'paper', off: [3, -3] }, // TR: paper on a 56 × 56 pink square, off register
  { dx: -30, dy: -30, tint: 'yellow', ink: 'ink', off: [0, 0] }, // BL: ink on yellow
  { dx: 30, dy: -30, tint: 'blue', ink: 'ink', off: [-3, 3] }, // BR: ink on blue, off register
];
/** Each quarantined card's 2×2. On (7, 3), the one in his 8-neighbourhood, the yellow quadrant is the one farthest from his card (TL). */
export const marilyn = (col: number, row: number): readonly Marilyn[] => {
  if (!near(S08_HERO, col, row)) return MARILYN;
  // His card seen from this one (y up: a lower row is further down).
  const hx = (S08_HERO[0] - col) * S08_GRID.cell;
  const hy = (row - S08_HERO[1]) * S08_GRID.cell;
  const away = (q: Marilyn) => Math.hypot(q.dx - hx, q.dy - hy);
  const far = MARILYN.reduce((a, q) => (away(q) > away(a) ? q : a));
  const yellow = MARILYN.find((q) => q.tint === 'yellow')!;
  // The farthest quadrant and the yellow one trade prints.
  return MARILYN.map((q) => (q === far ? { ...q, tint: yellow.tint, ink: yellow.ink, off: yellow.off } : q === yellow ? { ...q, tint: far.tint, ink: far.ink, off: far.off } : q));
};

