/**
 * Müller-Brockmann's arcs round the lens (the Beethoven poster's technique; ours: the antivirus's aperture): ring k (0–5) at radius
 * radii[k], stroke widths[k], 4 + k black segments with gaps of 8–20° (hashed per ring), fanning only over −35° … +150° (up and right,
 * the frame crops them; the lower-left quadrant stays his). Drawn rules < arcs < disc < hero. They print outward on 482 + 2k, step
 * ±11° on the kicks of 1.2 and 1.3 (alternate rings turn opposite ways; launch τ 1.5, no bounce), ride with the lens on 1.4 and tighten
 * to 92 % (launch τ 3), breathe 1 % on the hats and blow out (×1.6, α → 0) over 576–582. Stills fallback: the first four rings.
 */
export const ARCS = {
  radii: [390, 470, 550, 640, 740, 860],
  widths: [22, 16, 12, 9, 7, 5],
  segments: (k: number): number => 4 + k,
  gapDeg: [8, 20],
  fanDeg: [-35, 150],
  stepDeg: 11,
  tighten: 0.92,
  breathe: 0.01,
  blowOut: 1.6,
  fallbackRings: 4,
} as const;
