/** The third hit (swiss 3.4): a launch (τ 4) of these deltas to the glass's pose, turning him back toward us; the truck decelerates with τ 10 from v04's slope (200 px / 84 frames). */
export const HIT3_POSE = { ry: -0.45, rx: -0.08, rz: 0.03, x: -20, tau: 4, truckTau: 10 } as const;
/** The disc breathes r 300 → 330 over 744–767 (pre-iris), and the iris opens it as a red annulus r 330 → 1250 over 768–774 (launch τ 2: 75 % by 770). */
export const IRIS_RING = { breathe: [300, 330], open: [330, 1250], annulus: 140, tau: 2 } as const;
/** The living drift after the stamp (811–851): rz ±0.01 on a 48-frame sine, x ±3 px; from 816 a push of 2.5 % a beat about OMEGA_AT. */
export const SCAN_DRIFT = { rz: 0.01, period: 48, x: 3, push: 0.025 } as const;

// ——— S07b: the antivirus's POV (swiss 4) ————————————————————————————————————————————————————————————————————————————————————————

/**
 * The antivirus's POV signature (the story bible's 杀毒视角; S07b is its reference, the club, the interlude and drop 2 adapt it): bone on
 * near-black, a Sobel edge, red scanlines crawling, a red reticle with four inward ticks and an open centre, the readout in the slot
 * bottom-left (src/content/boot.ts READOUT_SLOT). Colours are display hex; the red is DEFENDER red (worlds/swiss.ts SWISS.red).
 */
export const DEFENDER_POV = {
  ground: '#0B1216',
  bone: '#CFE0E6',
  ink: 0.85,
  rules: 0.45,
  edge: 0.6,
  red: '#E8402B',
  scanlines: { width: 2, pitch: 9, alpha: 0.16, crawl: 3 },
  reticle: { r: 92, width: 4, ticks: 4, tick: 18, y: 40, hopTau: 1 },
  ping: { r: [92, 160], frames: 8 },
  stamp: { px: 13, weight: 500, cleanAlpha: 0.7, tab: 4, offset: [10, -10] },
} as const;
/** S07's 12 × 12 module grid the reticle scans (160 × 90 px cells, the poster's own module), column k's centre x (k = 0 … 11: −880 … +880). */
export const POV_GRID = { cols: 12, rows: 12, cellW: 160, cellH: 90 } as const;
export const reticleX = (k: number): number => -880 + POV_GRID.cellW * k;

/** The stamp on every cell of S07's 12 × 12 module grid (JetBrains Mono 500, 13 px: `clean` bone 0.7, `✓` red). */
export const CLEAN = 'clean ✓';
/** The POV readout (readout slot, JetBrains Mono 19 px): `· 0 threats` on every frame of the scan; the ✓ only from 810. `[SCAN]` and ✓ red. */
export const povReadout = (cells: number, done = false): string => `[SCAN] grid ${String(cells).padStart(3, '0')}/144 · 0 threats${done ? ' ✓' : ''}`;
/** Every POV string: the readout at each hop (+12 cells a hop, 000 … 144), its ✓ form from 810, the stamp. */
export const POV_TEXTS: readonly string[] = [...Array.from({ length: 13 }, (_, k) => povReadout(12 * k)), povReadout(144, true), CLEAN];

// ——— Atlases ————————————————————————————————————————————————————————————————————————————————————————————————————————————————————

const chars = (strings: readonly string[]): string[] => [...new Set(strings.join(''))].filter((c) => c !== ' ' && c !== '　');

/** Every face S06 and S08 draw (jp atlas): the hosts, him, his blink, the guest. */
export const SWISS_CAST: readonly string[] = [...S06_HOSTS.level1, ...S06_HOSTS.level2, ...S06_HOSTS.level3, ...S08_FACES, HERO, HERO_BLINK, GUEST];
export const SWISS_JP: readonly string[] = chars([...SWISS_FACES.map(faceText), SHUT, ...SWISS_CAST]);
// GLASS_TYPE (N2) comes last in its atlases: its new characters pack after every approved cell, so none of those moves.
export const SWISS_DISPLAY: readonly string[] = chars(['0123456789/', S08_HEADLINE, S08_FOOTER, GLASS_TYPE.big]);
export const SWISS_TEXT: readonly string[] = chars([LABELS.title, LABELS.footer, LABELS.bpm, LABELS.sig, GLASS_TYPE.small]);
/** The POV's mono atlas (readout, stamps). */
export const SWISS_MONO: readonly string[] = chars([...POV_TEXTS, '0123456789']);
/** The Riso world's characters as approved (the mouths as v04 set them), with A8's slug (the signature by the bottom-left registration mark, 960–1055). */
const RISO_APPROVED: readonly string[] = chars([...RISO_FACES.map(faceText), SHUT, ...FLIPBOOK.flat(), ...MOUTH_FACES.map((m) => m.setAs ?? m.face), '●', SIGNATURE]);
/** Characters the Riso world gained since (N1: the ・ of Σ(・ロ・)): the scene packs them after the mouths' counters, so no approved cell moves. */
export const RISO_ADDED: readonly string[] = chars(MOUTH_FACES.map((m) => m.face)).filter((c) => !RISO_APPROVED.includes(c));
/** Every character the Riso world draws: the approved ones in their order, then the added ones. */
export const RISO_GLYPHS: readonly string[] = [...RISO_APPROVED, ...RISO_ADDED];

/** Every string the build draws, for check-glyphs. */
export const BUILD_TEXTS: readonly TextItem[] = [
  ...SWISS_FACES.map((k) => ({ role: 'jp' as const, text: faceText(k), where: 'swiss faces (v04)' })),
  ...SWISS_CAST.map((text) => ({ role: 'jp' as const, text, where: 'S06 / S08 cast' })),
  { role: 'jp', text: SHUT, where: 'swiss blink' },
  { role: 'display', text: '0123456789/', where: 'swiss counter and 150 (v04: cleanCorner / glassBytes off)' },
  ...Object.values(GLASS_TYPE).map((text) => ({ role: 'display' as const, text, where: 'S07 glass type (N2)' })),
  { role: 'display', text: S08_HEADLINE, where: 'S08 headline cards' },
  { role: 'display', text: S08_FOOTER, where: 'S08 footer cards' },
  ...Object.values(LABELS).map((text) => ({ role: 'display' as const, text, where: 'swiss labels' })),
  ...POV_TEXTS.map((text) => ({ role: 'mono' as const, text, where: 'S07b POV' })),
  ...RISO_FACES.map((k) => ({ role: 'rounded' as const, text: faceText(k), where: 'riso faces' })),
  ...HALFTONE_FACES.map((text) => ({ role: 'rounded' as const, text, where: 'halftone faces' })),
  ...FLIPBOOK.flat().map((text) => ({ role: 'rounded' as const, text, where: 'S09 flipbook' })),
  ...MOUTH_FACES.map((m) => ({ role: 'rounded' as const, text: m.face, where: 'S10 mouths' })),
  ...[SHUT, '●'].map((text) => ({ role: 'rounded' as const, text, where: 'riso pieces' })),
  { role: 'rounded', text: SIGNATURE, where: 'riso slug (A8)' },
];
